export function itemWeightClass(slot, id, item) {
  if (frames[slot]) {
    const chassis = PARTS[slot]?.[id]?.chassis || id;
    return chassis === 'light' ? 'light' : chassis === 'heavy' ? 'heavy' : 'medium';
  }
  const tier = slot === 'equip2' ? [4, 5] : [6, 11];
  return item.weight <= tier[0] ? 'light' : item.weight <= tier[1] ? 'medium' : 'heavy';
}
export function itemIcon(slot, id, item) {
  const tier = itemWeightClass(slot, id, item),
    index = ['light', 'medium', 'heavy'].indexOf(tier);
  const path = designIcons[slot]?.[id] || frames[slot]?.[index] || equipment[id] || equipment.emp;
  return `<svg viewBox="0 0 64 64" aria-hidden="true" class="item-silhouette ${tier}"><path d="${path}"/></svg>`;
}
